  { "id": "intune-device-only", "name": "Microsoft Intune device-only subscription", "family": "security", "type": "standalone", "rank": 10, "note": "Per-device Intune subscription for devices not tied to a user - kiosks, dedicated devices, phone-room devices, IoT. Supports device-targeted policies and apps but not app protection policies, Conditional Access or user-based features like email.", "includes": [], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/intune/intune-service/fundamentals/licenses" },
  { "id": "exo-p1", "name": "Exchange Online Plan 1", "family": "m365", "type": "standalone", "rank": 12, "note": "Hosted business email with a 50 GB primary mailbox. No large archive or litigation hold unless the Exchange Online Archiving add-on is also assigned. Included in Office 365 E1 and the Business family suites.", "includes": [], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/exchange-online-service-description/exchange-online-limits" },
  { "id": "exo-p2", "name": "Exchange Online Plan 2", "family": "m365", "type": "standalone", "rank": 16, "note": "Hosted email with a 100 GB primary mailbox, an archive mailbox with auto-expanding archiving up to 1.5 TB, In-Place Hold and Litigation Hold, and data loss prevention. Included in Office 365 E3/E5 and Microsoft 365 E3/E5.", "includes": ["exo-p1"], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/exchange-online-service-description/exchange-online-limits" },
  { "id": "exo-archiving", "name": "Exchange Online Archiving", "family": "m365", "type": "addon", "rank": 8, "note": "Add-on for an Exchange Online Plan 1 mailbox (or an on-premises mailbox). Adds an archive mailbox with auto-expanding archiving up to 1.5 TB, plus In-Place Hold and Litigation Hold. Not needed where Exchange Online Plan 2 (or a suite that includes it) is present.", "includes": [], "prerequisites": ["Exchange Online Plan 1 (standalone or via a suite), or an on-premises Exchange mailbox"], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/exchange-online-archiving-service-description/exchange-online-archiving-service-description" },
  { "id": "spo-p1", "name": "SharePoint Online Plan 1", "family": "m365", "type": "standalone", "rank": 10, "note": "Team sites, document libraries and intranet with standard capacity. Included in Office 365 E1/F3 and the Business family suites.", "includes": [], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/office-365-platform-service-description/office-365-plan-options" },
  { "id": "spo-p2", "name": "SharePoint Online Plan 2", "family": "m365", "type": "standalone", "rank": 14, "note": "SharePoint with higher limits and eDiscovery/records features. Included in Office 365 E3/E5 and Microsoft 365 E3/E5.", "includes": ["spo-p1"], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/office-365-platform-service-description/office-365-plan-options" },
  { "id": "spo-advanced-mgmt", "name": "SharePoint Advanced Management Plan 1", "family": "m365", "type": "addon", "rank": 20, "note": "Add-on (also called SharePoint Advanced Management standalone) for oversharing and access governance: data access governance reports, restricted access control, restricted site creation, site lifecycle policies. Also granted automatically when at least one user in the tenant has a Microsoft 365 Copilot licence, and included in Microsoft 365 E7.", "includes": [], "prerequisites": ["SharePoint K, Plan 1 or Plan 2 in the tenant"], "source": "https://learn.microsoft.com/en-us/sharepoint/sharepoint-advanced-management-prerequisites" },
  { "id": "onedrive-p1", "name": "OneDrive for work and school Plan 1", "family": "m365", "type": "standalone", "rank": 8, "note": "Standalone per-user OneDrive cloud storage with standard capacity. Included in the Business family suites and Office 365 E1.", "includes": [], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/office-365-platform-service-description/office-365-plan-options" },
  { "id": "onedrive-p2", "name": "OneDrive for work and school Plan 2", "family": "m365", "type": "standalone", "rank": 10, "note": "Standalone OneDrive storage with unlimited/large capacity and advanced compliance. Included in Office 365 E3/E5 and Microsoft 365 E3/E5.", "includes": ["onedrive-p1"], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/office-365-platform-service-description/office-365-plan-options" },
  { "id": "teams-eea", "name": "Microsoft Teams EEA", "family": "m365", "type": "standalone", "rank": 12, "note": "The Teams standalone SKU offered to customers in the European Economic Area and Switzerland, where Teams is unbundled from Office 365 / Microsoft 365. Functionally equivalent to Microsoft Teams Enterprise for licensing purposes.", "includes": [], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/microsoftteams/teams-add-on-licensing/microsoft-teams-add-on-licensing" },
  { "id": "teams-phone", "name": "Microsoft Teams Phone", "family": "m365", "type": "addon", "rank": 20, "note": "Cloud PBX add-on (formerly Phone System): calling in Teams, auto attendants and call queues. Requires PSTN connectivity added separately - Calling Plan, Operator Connect or Direct Routing. Included in Office 365 E5 and Microsoft 365 E5. On-premises PSTN needs only Teams Phone Standard, not a Calling Plan.", "includes": [], "prerequisites": ["A Teams licence", "A separate PSTN connectivity option"], "source": "https://learn.microsoft.com/en-us/microsoftteams/teams-add-on-licensing/microsoft-teams-add-on-licensing" },
  { "id": "teams-phone-calling-plan", "name": "Microsoft Teams Calling Plan", "family": "m365", "type": "addon", "rank": 22, "note": "Add-on that makes Microsoft the PSTN carrier for Teams Phone (domestic or international), with a monthly pooled minute allowance. Communication Credits can be added for overage and toll-no-cost scenarios.", "includes": ["teams-phone"], "prerequisites": ["Teams Phone", "A Teams licence"], "source": "https://learn.microsoft.com/en-us/microsoftteams/teams-add-on-licensing/microsoft-teams-add-on-licensing" },
  { "id": "teams-audio-conferencing", "name": "Microsoft Teams Audio Conferencing", "family": "m365", "type": "addon", "rank": 12, "note": "Add-on that lets meeting attendees dial in to Teams meetings by phone (PSTN conferencing). A no-cost Audio Conferencing licence covers dial-in plus outbound calls to the US and Canada; the standard licence adds toll numbers worldwide and 60 pooled outbound minutes/user/month. Included in Office 365 E5 and Microsoft 365 E5.", "includes": [], "prerequisites": ["A qualifying Microsoft 365 / Office 365 subscription with Teams"], "source": "https://learn.microsoft.com/en-us/microsoftteams/teams-add-on-licensing/microsoft-teams-add-on-licensing" },
  { "id": "teams-premium", "name": "Microsoft Teams Premium", "family": "m365", "type": "addon", "rank": 30, "note": "Per-user add-on on top of a Teams licence: intelligent meeting recap for more scenarios, live translated captions/transcripts, meeting templates and branding, advanced meeting protection (watermark, end-to-end encryption, sensitivity labels, prevent copy), advanced collaboration analytics, advanced Bookings, and the Queues app (with Teams Phone). Requires both a Teams licence and a Teams Premium licence.", "includes": [], "prerequisites": ["An Office 365 / Microsoft 365 subscription and a Teams licence"], "source": "https://learn.microsoft.com/en-us/microsoftteams/enhanced-teams-experience" },
  { "id": "teams-rooms-pro", "name": "Microsoft Teams Rooms Pro", "family": "m365", "type": "addon", "rank": 25, "note": "Per-device licence for a certified Teams Rooms system or Teams panel: enhanced in-room meeting experiences (Front row, intelligent audio/video, dual screen), Pro management portal, Teams Phone Standard, Audio Conferencing, Intune, Entra ID P1 and Defender for Endpoint P2 for the device. Assigned to the room resource account, not to users.", "includes": ["teams-audio-conferencing", "teams-phone", "entra-p1", "intune-p1", "mde-p2"], "prerequisites": ["A certified Microsoft Teams Rooms device or Teams panel"], "source": "https://learn.microsoft.com/en-us/microsoftteams/rooms/rooms-licensing" },
  { "id": "teams-rooms-basic", "name": "Microsoft Teams Rooms Basic", "family": "m365", "type": "addon", "rank": 6, "note": "No-cost per-device licence for up to 25 certified Teams Rooms systems: schedule and join meetings, share content, whiteboard, Audio Conferencing, plus basic inventory/monitoring. Payment details are required at sign-up but no charge is made. Above 25 rooms, or for Teams panels, use Teams Rooms Pro.", "includes": ["teams-audio-conferencing"], "prerequisites": ["A certified Microsoft Teams Rooms system", "Maximum 25 per tenant"], "source": "https://learn.microsoft.com/en-us/microsoftteams/rooms/rooms-licensing" },
  { "id": "teams-shared-space", "name": "Microsoft Teams Shared Space", "family": "m365", "type": "addon", "rank": 10, "note": "Per-device add-on (renamed from Microsoft Teams Shared Devices in April 2026) for shared endpoints: common-area phones, desk docks for bookable desks, and Teams panels for meeting spaces. Not valid on Teams Rooms systems - those need a Teams Rooms Basic or Pro licence.", "includes": [], "prerequisites": ["A supported shared Teams device"], "source": "https://learn.microsoft.com/en-us/microsoftteams/teams-add-on-licensing/microsoft-teams-add-on-licensing" },
  { "id": "viva-suite", "name": "Microsoft Viva Suite", "family": "m365", "type": "suite", "rank": 40, "note": "Per-user add-on bundling every paid Viva module: Viva Insights (incl. advanced/manager/leader insights), Viva Learning (with LMS integration), Viva Glint, Viva Pulse, Viva Amplify, Viva Engage premium and Answers in Viva.", "includes": ["viva-insights", "viva-glint", "viva-learning", "viva-pulse", "viva-comms"], "prerequisites": ["A Microsoft 365 / Office 365 plan that enables the user for Viva"], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-viva-service-description" },
  { "id": "viva-waef", "name": "Microsoft Viva Workplace Analytics and Employee Feedback", "family": "m365", "type": "addon", "rank": 32, "note": "Per-user add-on giving the analytics and feedback modules only: Viva Insights (advanced/manager/leader), Viva Glint and Viva Pulse. A subset of the full Viva Suite.", "includes": ["viva-insights", "viva-glint", "viva-pulse"], "prerequisites": ["A Microsoft 365 / Office 365 plan that enables the user for Viva"], "source": "https://learn.microsoft.com/en-us/viva/pulse/get-started/licensing-requirements" },
  { "id": "viva-insights", "name": "Microsoft Viva Insights", "family": "m365", "type": "addon", "rank": 20, "note": "Per-user add-on for workplace analytics: manager and leader insights, advanced analysis tools, custom query engine and prebuilt accelerators, plus premium personal insights. Requires Exchange Online. Personal insights (Headspace, focus plans, briefing) are already free with most Microsoft 365 plans. The Copilot Dashboard / Advanced Copilot Reporting comes with Microsoft 365 Copilot or 10 Insights licences.", "includes": [], "prerequisites": ["A Microsoft 365 / Office 365 plan with Exchange Online Plan 1 or 2"], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-viva-service-description" },
  { "id": "viva-glint", "name": "Microsoft Viva Glint", "family": "m365", "type": "addon", "rank": 18, "note": "Per-user 'voice of the employee' add-on: org-wide engagement surveys, people-science templates and action plans, comment analytics, benchmarks and predictive analytics. A Glint licence also grants Viva Pulse.", "includes": ["viva-pulse"], "prerequisites": ["A Microsoft 365 / Office 365 plan that enables the user for Viva"], "source": "https://learn.microsoft.com/en-us/viva/pulse/get-started/licensing-requirements" },
  { "id": "viva-learning", "name": "Microsoft Viva Learning", "family": "m365", "type": "addon", "rank": 16, "note": "Per-user add-on unlocking the premium Viva Learning features: LMS and partner content-provider integration, content recommendation and completion tracking, adding learning to the calendar, and surfacing learning in Microsoft Search. The free tier (Teams app, org content, 125 LinkedIn Learning courses, Microsoft Learn) is in every Microsoft 365 plan.", "includes": [], "prerequisites": ["A Microsoft 365 / Office 365 plan that enables the user for Viva"], "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-viva-service-description" },
  { "id": "viva-pulse", "name": "Microsoft Viva Pulse", "family": "m365", "type": "addon", "rank": 12, "note": "Per-user add-on for lightweight, confidential team feedback surveys with research-backed templates and Copilot report summaries. Also included with Viva Glint, Viva Workplace Analytics and Employee Feedback, and the Viva Suite.", "includes": [], "prerequisites": ["A Microsoft 365 / Office 365 plan that enables the user for Viva"], "source": "https://learn.microsoft.com/en-us/viva/pulse/get-started/licensing-requirements" },
  { "id": "viva-comms", "name": "Microsoft Viva Employee Communities and Communications", "family": "m365", "type": "addon", "rank": 16, "note": "Per-user add-on for internal communicators: enables Viva Amplify (multi-channel campaign publishing and reporting) and Viva Engage premium (leadership corner, campaigns, advanced analytics, Answers). Amplify needs OneDrive and an Exchange mailbox.", "includes": [], "prerequisites": ["A Microsoft 365 / Office 365 plan that enables the user for Viva", "OneDrive and an Exchange mailbox for Amplify"], "source": "https://learn.microsoft.com/en-us/viva/amplify/set-up-viva-amplify" },
  { "id": "teams-comm-credits", "name": "Communication Credits", "family": "m365", "type": "consumption", "rank": 6, "note": "A prepaid pool of minutes for PSTN calls beyond a Calling Plan allowance, and to enable toll-free numbers for Audio Conferencing, auto attendants and call queues. Consumption-based; can be disabled to avoid charges.", "includes": [], "prerequisites": ["Teams Phone or Audio Conferencing"], "source": "https://learn.microsoft.com/en-us/microsoftteams/teams-add-on-licensing/microsoft-teams-add-on-licensing" },
  { "id": "exo-hve", "name": "Exchange Online High Volume Email", "family": "m365", "type": "consumption", "rank": 5, "note": "Pay-as-you-go Exchange Online service for line-of-business apps and devices that send large volumes of automated, transactional or operational internal email, using dedicated service accounts. Billed on expanded recipients.", "includes": [], "prerequisites": ["An Exchange Online / Microsoft 365 tenant; an Azure subscription for billing"], "source": "https://learn.microsoft.com/en-us/microsoft-365/commerce/services/pay-as-you-go-services" },
  { "id": "entra-workload-id", "name": "Microsoft Entra Workload ID", "family": "security", "type": "standalone", "rank": 15, "note": "Adds Conditional Access, risk detection and access reviews for application identities and service principals. Licensed per workload identity per month.", "includes": [], "prerequisites": [], "source": "https://learn.microsoft.com/en-us/entra/fundamentals/licensing" },
  { "id": "entra-domain-services", "name": "Microsoft Entra Domain Services", "family": "security", "type": "consumption", "rank": 12, "note": "A managed domain (LDAP, Kerberos, NTLM, domain join, group policy) for legacy apps, with no domain controllers to manage. Charges accrue per hour based on the SKU the tenant owner selects.", "includes": [], "prerequisites": ["An Azure subscription"], "source": "https://learn.microsoft.com/en-us/entra/fundamentals/licensing" },
  { "id": "mdo-p1", "name": "Microsoft Defender for Office 365 Plan 1", "family": "security", "type": "addon", "rank": 22, "prerequisites": ["Exchange Online via a qualifying Office 365 / Microsoft 365 plan"], "note": "Safe Attachments, Safe Links, Safe Attachments for SharePoint/OneDrive/Teams, anti-phishing and real-time detections. Standalone, or in Microsoft 365 Business Premium and Office 365 / Microsoft 365 E5.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "mde-p1", "name": "Microsoft Defender for Endpoint Plan 1", "family": "security", "type": "addon", "rank": 22, "prerequisites": ["A supported OS and a qualifying per-user or per-device licence"], "note": "Next-generation antimalware, attack surface reduction rules, device control, endpoint firewall, web/network protection and application control. Included in Microsoft 365 E3/A3/G3. No EDR.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "mdi", "name": "Microsoft Defender for Identity", "family": "security", "type": "standalone", "rank": 25, "prerequisites": [], "note": "Per-user cloud service that detects identity attacks and compromised accounts across on-prem Active Directory and hybrid identity. Standalone, or in EMS E5 and Microsoft 365 E5.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "mdca", "name": "Microsoft Defender for Cloud Apps", "family": "security", "type": "standalone", "rank": 28, "prerequisites": [], "note": "CASB / SaaS security: cloud app discovery, app governance for OAuth apps, session and access control, and threat protection for SaaS. Standalone, or in EMS E5 and Microsoft 365 E5.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "mdvm-standalone", "name": "Microsoft Defender Vulnerability Management (standalone)", "family": "security", "type": "standalone", "rank": 20, "prerequisites": [], "note": "Full vulnerability management (core plus premium capabilities) for organisations that do not have Defender for Endpoint Plan 2. Per-user subscription.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "mdvm-addon", "name": "Microsoft Defender Vulnerability Management add-on", "family": "security", "type": "addon", "rank": 15, "prerequisites": ["Microsoft Defender for Endpoint Plan 2, or a plan that includes it"], "note": "Premium vulnerability management tools (security baselines assessment, browser extension and certificate inventory, blocking vulnerable apps, and more) added onto Defender for Endpoint Plan 2.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "eiot-addon", "name": "Microsoft Defender for IoT - EIoT Device License add-on", "family": "security", "type": "addon", "rank": 12, "prerequisites": ["Microsoft Defender for Endpoint Plan 2, or a subscription that includes it"], "note": "Per-device add-on that brings enterprise IoT devices (printers, cameras, VoIP phones) under Defender for Endpoint vulnerability and threat monitoring.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "mdti-premium", "name": "Microsoft Defender Threat Intelligence Premium", "family": "security", "type": "standalone", "rank": 18, "prerequisites": [], "note": "Full threat-intelligence portal: Microsoft-curated IOCs and enriched OSINT, finished intel articles, threat actor and infrastructure analysis. A standalone licence beyond the limited free/Defender tier.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "defender-experts-xdr", "name": "Microsoft Defender Experts for XDR", "family": "security", "type": "addon", "rank": 20, "prerequisites": ["Microsoft 365 E5, or Microsoft 365 E3 + the Defender suite / EMS E5 add-on"], "note": "Managed extended detection and response: Microsoft analysts triage, investigate and (optionally) respond to incidents across the Defender XDR workloads on the customer's behalf. Sold as a service on top of a qualifying Defender suite.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "defender-experts-hunting", "name": "Microsoft Defender Experts for Hunting", "family": "security", "type": "addon", "rank": 18, "prerequisites": ["Defender for Endpoint Plan 2; optionally Defender for Office 365 P2, Defender for Identity, Defender for Cloud Apps, Entra ID P2"], "note": "Managed proactive threat hunting across endpoints, email, identity and cloud apps, with Defender Experts Notifications and Ask Defender Experts. For customers who run their own SOC.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "defender-business", "name": "Microsoft Defender for Business", "family": "security", "type": "standalone", "rank": 20, "prerequisites": ["Up to 300 employees"], "note": "Endpoint security (next-gen protection, EDR, automated investigation) for organisations up to 300 employees. Included in Microsoft 365 Business Premium, or standalone. Servers need the Defender for Business servers add-on.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-defender-service-description" },
  { "id": "defender-servers-p1", "name": "Microsoft Defender for Servers Plan 1", "family": "azure", "type": "consumption", "rank": 18, "prerequisites": [], "note": "Per-server Defender for Cloud plan that licenses Defender for Endpoint on server OSEs (EDR, automatic onboarding, integrated alerts). Billed per server hour through an Azure subscription.", "source": "https://learn.microsoft.com/azure/defender-for-cloud/defender-for-servers-overview" },
  { "id": "defender-servers-p2", "name": "Microsoft Defender for Servers Plan 2", "family": "azure", "type": "consumption", "rank": 26, "prerequisites": [], "note": "Everything in Plan 1 plus agentless scanning, premium Defender Vulnerability Management, file integrity monitoring, just-in-time VM access and free data ingestion allowance. Billed per server hour.", "source": "https://learn.microsoft.com/azure/defender-for-cloud/defender-for-servers-overview" },
  { "id": "defender-cspm", "name": "Microsoft Defender Cloud Security Posture Management (Defender CSPM)", "family": "azure", "type": "consumption", "rank": 22, "prerequisites": [], "note": "Paid Defender for Cloud posture plan: attack path analysis, cloud security explorer, agentless scanning, data and AI security posture, regulatory compliance and governance across Azure, AWS and GCP. Billed per billable resource.", "source": "https://learn.microsoft.com/azure/defender-for-cloud/concept-cloud-security-posture-management" },
  { "id": "defender-cloud-cwp", "name": "Microsoft Defender for Cloud - workload protection plan", "family": "azure", "type": "consumption", "rank": 20, "prerequisites": [], "note": "Any of the resource-specific Defender for Cloud plans (Storage, SQL, Containers, App Service, Key Vault, Resource Manager, APIs, etc.). Each is enabled per subscription/resource and billed on consumption.", "source": "https://learn.microsoft.com/azure/defender-for-cloud/defender-for-cloud-introduction" },
  { "id": "security-copilot", "name": "Microsoft Security Copilot", "family": "security", "type": "consumption", "rank": 30, "prerequisites": [], "note": "Generative-AI assistance across the Security Copilot portal and embedded in Defender, Purview, Intune and Entra. Metered in Security Compute Units (SCUs) - provisioned hourly capacity plus optional overage; Microsoft 365 E5/E7 tenants get an included monthly SCU allocation.", "source": "https://learn.microsoft.com/copilot/security/security-compute-units-capacity" },
  { "id": "intune-p2", "name": "Microsoft Intune Plan 2", "family": "security", "type": "addon", "rank": 24, "prerequisites": ["Microsoft Intune Plan 1 (standalone or via a suite)"], "note": "Additive to Intune Plan 1. Adds Remote Help, Advanced Analytics, Microsoft Tunnel for MAM, firmware-over-the-air updates and specialty (AR/VR, meeting-room) device management.", "source": "https://learn.microsoft.com/en-us/intune/intune-service/fundamentals/licenses" },
  { "id": "intune-epm", "name": "Microsoft Intune Endpoint Privilege Management", "family": "security", "type": "addon", "rank": 14, "prerequisites": ["Microsoft Intune Plan 1"], "note": "Standalone Intune Suite add-on. Lets standard users run approved tasks with elevation without holding local admin rights.", "source": "https://learn.microsoft.com/intune/fundamentals/add-ons" },
  { "id": "intune-remote-help", "name": "Microsoft Intune Remote Help", "family": "security", "type": "addon", "rank": 12, "prerequisites": ["Microsoft Intune Plan 1"], "note": "Standalone Intune add-on. Authenticated, compliance-aware remote view and control of managed devices with role-based access, plus Azure Virtual Desktop / RemoteApp support.", "source": "https://learn.microsoft.com/intune/fundamentals/add-ons" },
  { "id": "intune-advanced-analytics", "name": "Microsoft Intune Advanced Analytics", "family": "security", "type": "addon", "rank": 14, "prerequisites": ["Microsoft Intune Plan 1"], "note": "Standalone Intune add-on. Endpoint analytics anomaly detection, enhanced device timeline, device query (near-real-time device state), battery health and custom device scopes.", "source": "https://learn.microsoft.com/intune/fundamentals/advanced-capabilities" },
  { "id": "intune-enterprise-app-mgmt", "name": "Microsoft Intune Enterprise App Management", "family": "security", "type": "addon", "rank": 14, "prerequisites": ["Microsoft Intune Plan 1"], "note": "Standalone Intune add-on. Enterprise App Catalog of curated Win32 apps with pre-set install/detection settings, Microsoft-hosted app content and app update management.", "source": "https://learn.microsoft.com/intune/fundamentals/add-ons" },
  { "id": "intune-cloud-pki", "name": "Microsoft Cloud PKI", "family": "security", "type": "addon", "rank": 16, "prerequisites": ["Microsoft Intune Plan 1"], "note": "Standalone Intune add-on. A Microsoft-managed certificate authority that issues, renews and revokes device certificates across all Intune-supported platforms without on-prem PKI/NDES.", "source": "https://learn.microsoft.com/intune/fundamentals/add-ons" },
  { "id": "intune-tunnel-mam", "name": "Microsoft Tunnel for Mobile Application Management", "family": "security", "type": "addon", "rank": 12, "prerequisites": ["Microsoft Intune Plan 1 plus Intune Plan 2 or Intune Suite"], "note": "Extends the Microsoft Tunnel VPN gateway to unenrolled Android and iOS devices. Available only through Intune Plan 2 or the Intune Suite - not sold as an individual standalone add-on.", "source": "https://learn.microsoft.com/intune/fundamentals/add-ons" },
  { "id": "aip-p1", "name": "Azure Information Protection Plan 1", "family": "security", "type": "standalone", "rank": 12, "prerequisites": [], "note": "Manual sensitivity labelling and protection (Azure RMS), and Office 365 Message Encryption rights. Included in EMS E3/E5 and Microsoft 365 E3 and above.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-purview-service-description" },
  { "id": "aip-p2", "name": "Azure Information Protection Plan 2", "family": "security", "type": "standalone", "rank": 18, "prerequisites": ["AIP Plan 1 must also be assigned for labelling to be available"], "note": "Everything in AIP P1 plus automatic and recommended client-side labelling, and automatic classification. Included in EMS E5 and Microsoft 365 E5. Also called Information Protection for Office 365 - Premium.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-purview-service-description" },
  { "id": "purview-ipg", "name": "Microsoft 365 E5 Information Protection and Governance", "family": "security", "type": "addon", "rank": 40, "prerequisites": ["Microsoft 365 E3 or the equivalent components"], "note": "Add-on for Microsoft 365 E3. The information-protection and data-governance half of E5 Compliance: automatic sensitivity labelling, endpoint DLP, DLP for Teams, records management, trainable classifiers, Customer Key.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-purview-service-description" },
  { "id": "purview-eda-audit", "name": "Microsoft 365 E5 eDiscovery and Audit", "family": "security", "type": "addon", "rank": 38, "prerequisites": ["Microsoft 365 E3 or the equivalent components"], "note": "Add-on for Microsoft 365 E3. eDiscovery (Premium) end-to-end workflow and Audit (Premium) one-year (and add-on 10-year) log retention with high-value events.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-purview-service-description" },
  { "id": "purview-irm", "name": "Microsoft 365 E5 Insider Risk Management", "family": "security", "type": "addon", "rank": 36, "prerequisites": ["Microsoft 365 E3 or the equivalent components"], "note": "Add-on for Microsoft 365 E3. Insider Risk Management, Communication Compliance, Customer Lockbox, Information Barriers and Privileged Access Management.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-purview-service-description" },
  { "id": "audit-10yr-addon", "name": "Microsoft Purview Audit (Premium) - 10-Year Audit Log Retention add-on", "family": "security", "type": "addon", "rank": 10, "prerequisites": ["Audit (Premium) via Microsoft 365 E5, E5 Compliance or E5 eDiscovery and Audit"], "note": "Per-user add-on that extends Audit (Premium) log retention from one year to ten years for the assigned users.", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-purview-service-description" },
  { "id": "exchange-online-p2", "name": "Exchange Online Plan 2", "family": "security", "type": "standalone", "rank": 14, "prerequisites": [], "note": "Adds a 100 GB mailbox, in-place hold / litigation hold and unlimited archiving. Needed for eDiscovery holds and some retention scenarios on standalone Exchange (Plan 1 needs the Exchange Online Archiving add-on instead).", "source": "https://learn.microsoft.com/en-us/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-purview-service-description" },
  { "id": "priva-prm", "name": "Microsoft Priva Privacy Risk Management", "family": "security", "type": "addon", "rank": 20, "prerequisites": ["Office 365 or Microsoft 365 E1/E3/E5/F-series or equivalent"], "note": "Add-on that surfaces personal data across Exchange, SharePoint, OneDrive and Teams and runs data-minimisation, overexposure and transfer risk policies with user remediation.", "source": "https://learn.microsoft.com/office365/servicedescriptions/microsoft-365-service-descriptions/microsoft-365-tenantlevel-services-licensing-guidance/microsoft-priva-service-description" },
  { "id": "priva-srr", "name": "Microsoft Priva Subject Rights Requests", "family": "security", "type": "addon", "rank": 12, "prerequisites": [], "note": "Per-request licence to run data subject rights requests (DSAR/DSR) - identify a data subject and collect and review their personal data across Exchange, SharePoint, OneDrive and Teams.", "source": "https://learn.microsoft.com/en-us/privacy/priva/subject-rights-requests" },
  { "id": "win-e5-user", "name": "Windows 11 Enterprise E5 (per user)", "family": "security", "type": "standalone", "rank": 22, "prerequisites": ["Each device already licensed for Windows 10/11 Pro"], "note": "Windows 11 Enterprise E3 per-user rights plus Microsoft Defender for Endpoint Plan 2. Per-user only, available through Commercial Licensing / CSP. Included in Microsoft 365 E5.", "source": "https://learn.microsoft.com/en-us/windows/whats-new/windows-licensing" },
  { "id": "win-vda", "name": "Windows Enterprise E3/E5 per-device (VDA)", "family": "security", "type": "standalone", "rank": 16, "prerequisites": [], "note": "Per-device Windows Enterprise licensing (Virtual Desktop Access, or per-device Enterprise). The route when devices are shared, not assigned to a user, or are thin clients not covered by a per-user Windows subscription.", "source": "https://learn.microsoft.com/en-us/windows/whats-new/windows-licensing" },
  { "id": "win-ltsc", "name": "Windows 11 Enterprise LTSC", "family": "security", "type": "standalone", "rank": 15, "prerequisites": ["A Windows Enterprise E3/E5 subscription (per-user) or Volume Licensing per-device"], "note": "Long-Term Servicing Channel edition for fixed-function / regulated devices: security and critical fixes only, no feature updates, up to 5 years support. Available per-user or per-device depending on the licensing program.", "source": "https://learn.microsoft.com/en-us/windows/whats-new/windows-licensing" },
  { "id": "w365-enterprise", "name": "Windows 365 Enterprise", "family": "security", "type": "addon", "rank": 30, "prerequisites": ["Windows 11/10 Enterprise E3+ , Microsoft Intune, Microsoft Entra ID P1"], "note": "Per-user fixed-price Cloud PC managed with Microsoft Intune. Requires Windows Enterprise E3 (or higher), Intune and Entra ID P1 alongside it. No seat limit.", "source": "https://learn.microsoft.com/windows-365/enterprise/requirements" },
  { "id": "w365-business", "name": "Windows 365 Business", "family": "security", "type": "suite", "rank": 26, "prerequisites": ["Up to 300 users"], "note": "Per-user Cloud PC for organisations up to 300 users, bought and managed simply without Intune or the Windows/Entra prerequisites.", "source": "https://learn.microsoft.com/office365/servicedescriptions/windows-365-service-description/windows-365-service-description" },
  { "id": "w365-frontline", "name": "Windows 365 Frontline (Windows 365 Flex)", "family": "security", "type": "addon", "rank": 24, "prerequisites": ["Windows 11/10 Enterprise E3+ , Microsoft Intune, Microsoft Entra ID P1"], "note": "Cloud PC licences assigned to the tenant and shared across shift/frontline workers (or used in dedicated mode). Requires Windows Enterprise E3+, Intune and Entra ID P1.", "source": "https://learn.microsoft.com/windows-365/enterprise/requirements" },
  { "id": "azure-reservation", "name": "Azure Reservations", "family": "azure", "type": "benefit", "rank": 8, "note": "A billing discount, not a product. Commit to a specific resource type in a region for one or three years to get a reduced rate. Covers the compute portion only, not software, OS, networking or storage, and does not reserve or guarantee capacity.", "prerequisites": ["An Azure subscription (EA, MCA or pay-as-you-go); Owner or Reservation Purchaser role"], "source": "https://learn.microsoft.com/azure/cost-management-billing/reservations/save-compute-costs-reservations" },
  { "id": "azure-savings-plan", "name": "Azure savings plan for compute", "family": "azure", "type": "benefit", "rank": 8, "note": "A billing discount where you commit to a fixed hourly compute spend for one or three years. The discount then applies automatically across VM families, regions and eligible compute services (VMs, App Service, Functions Premium, Container Instances, Container Apps, Dedicated Host). Does not cover software, networking or storage.", "prerequisites": ["Resources under an Enterprise Agreement, Microsoft Customer Agreement or Microsoft Partner Agreement"], "source": "https://learn.microsoft.com/azure/cost-management-billing/savings-plan/savings-plan-overview" },
  { "id": "azure-spot", "name": "Azure Spot Virtual Machines", "family": "azure", "type": "consumption", "rank": 6, "note": "Unused Azure capacity offered at a deep discount with no SLA. VMs can be evicted with about 30 seconds' notice when Azure needs the capacity back or the price exceeds your max price. Suited to interruptible batch, dev/test and large compute workloads.", "prerequisites": [], "source": "https://learn.microsoft.com/azure/virtual-machines/spot-vms" },
  { "id": "azure-hub-linux", "name": "Azure Hybrid Benefit for Linux", "family": "azure", "type": "benefit", "rank": 5, "note": "A right to switch a Red Hat Enterprise Linux or SUSE Linux Enterprise Server VM between pay-as-you-go (subscription billed by Azure) and bring-your-own-subscription (BYOS) billing, so an existing RHEL or SLES subscription covers the software fee and you pay only Azure infrastructure. Only RHEL images published by Red Hat and SLES pay-as-you-go images are eligible.", "prerequisites": ["An eligible RHEL or SLES cloud-access subscription for BYOS"], "source": "https://learn.microsoft.com/azure/virtual-machines/linux/azure-hybrid-benefit-linux" },
  { "id": "macc", "name": "Microsoft Azure Consumption Commitment (MACC)", "family": "azure", "type": "benefit", "rank": 5, "note": "A contractual commitment to spend a set amount on Azure over a period. Eligible first-party Azure usage and Azure-benefit-eligible Microsoft Marketplace purchases (100% of the pretax amount) draw the commitment down when bought through the Azure portal. Azure prepayment purchases and licences used on-premises or in hybrid don't count.", "prerequisites": ["An Azure Consumption Commitment in an Enterprise Agreement or Microsoft Customer Agreement"], "source": "https://learn.microsoft.com/marketplace/azure-consumption-commitment-benefit" },
  { "id": "vs-pro", "name": "Visual Studio Professional subscription", "family": "azure", "type": "standalone", "rank": 15, "note": "Per-user. The Visual Studio Professional IDE plus subscriber benefits: a monthly individual Azure dev/test credit, discounted Azure Dev/Test rates for non-production, Azure DevOps Basic plan, and software downloads.", "prerequisites": [], "source": "https://learn.microsoft.com/visualstudio/subscriptions/what-are-subscriptions" },
  { "id": "vs-enterprise", "name": "Visual Studio Enterprise subscription", "family": "azure", "type": "standalone", "rank": 25, "note": "Per-user. Visual Studio Enterprise IDE plus the largest set of subscriber benefits: the highest monthly Azure dev/test credit, discounted Azure Dev/Test rates, Azure DevOps Basic + Test Plans, a Microsoft 365 E5 developer subscription, and one extra self-hosted Azure Pipelines parallel job per subscriber.", "prerequisites": [], "source": "https://learn.microsoft.com/visualstudio/subscriptions/what-are-subscriptions" },
  { "id": "azure-devtest", "name": "Azure Dev/Test offers", "family": "azure", "type": "benefit", "rank": 8, "note": "Discounted Azure rates for non-production development and testing. Enterprise Dev/Test (offer 0148P) requires an Enterprise Agreement; Pay-As-You-Go Dev/Test (offer 0023P) does not. Both require every user of the subscription to hold an active Visual Studio subscription, and both unlock the Windows client images in Marketplace.", "prerequisites": ["Active Visual Studio subscriptions for all users; an Enterprise Agreement for the Enterprise Dev/Test offer"], "source": "https://learn.microsoft.com/azure/devtest/offer/overview-what-is-devtest-offer-visual-studio" },
  { "id": "azure-support-dev", "name": "Azure Developer support plan", "family": "azure", "type": "standalone", "rank": 8, "note": "Entry paid support. Technical break-fix support during business hours, plus the billing and subscription-management support that all customers get. Trial and production guidance only, no architecture or operational advisory.", "prerequisites": [], "source": "https://learn.microsoft.com/azure/azure-portal/supportability/how-to-create-azure-support-request" },
  { "id": "azure-support-standard", "name": "Azure Standard support plan", "family": "azure", "type": "standalone", "rank": 14, "note": "24x7 technical break-fix support with faster response times than Developer. The minimum plan for opening a Sev A ticket and for services such as Azure Local support requests.", "prerequisites": [], "source": "https://learn.microsoft.com/azure/azure-local/manage/get-support" },
  { "id": "azure-support-prodirect", "name": "Azure Professional Direct (ProDirect) support plan", "family": "azure", "type": "standalone", "rank": 22, "note": "For business-critical workloads. Fastest response, escalation management, ProDirect delivery managers, plus advisory and developer-mentoring services. Required (with Premier/Unified) to use the Azure Support REST API.", "prerequisites": [], "source": "https://learn.microsoft.com/rest/api/support/" },
  { "id": "azure-support-unified", "name": "Microsoft Unified support", "family": "azure", "type": "standalone", "rank": 40, "note": "Account-managed enterprise support across all Microsoft products (formerly Premier). Includes a customer success account manager, proactive services and the highest-severity Azure response. Also satisfies the Support REST API requirement.", "prerequisites": [], "source": "https://learn.microsoft.com/rest/api/support/" },
  { "id": "arc-servers", "name": "Azure Arc-enabled servers", "family": "azure", "type": "consumption", "rank": 6, "note": "Projects on-premises and other-cloud servers (and, similarly, Kubernetes clusters and VMware/SCVMM estates) into Azure. The control plane is free: resource organisation, tags, Azure Resource Graph, RBAC, templates and extensions. Any Azure service consumed through Arc (Monitor, Defender for Servers, Update Manager, Sentinel, Machine Configuration) is billed at its own rate.", "prerequisites": ["Azure Connected Machine agent installed and the server in a Connected state"], "source": "https://learn.microsoft.com/azure/azure-arc/overview" },
  { "id": "ws-payg-arc", "name": "Windows Server pay-as-you-go enabled by Azure Arc", "family": "azure", "type": "consumption", "rank": 10, "note": "A subscription alternative to perpetual Windows Server licensing for Windows Server 2025 and later. Connect the server to Azure Arc, enable pay-as-you-go, and the OS licence is billed per core per hour through Azure with no product key and no CALs for base functionality. Enrolment also includes the Windows Server management services at no extra cost.", "prerequisites": ["Windows Server 2025 or later; server connected to Azure Arc"], "source": "https://learn.microsoft.com/azure/azure-arc/servers/billing-windows-server-pay-go" },
  { "id": "ws-mgmt-arc", "name": "Windows Server Management enabled by Azure Arc", "family": "azure", "type": "benefit", "rank": 6, "note": "For Arc-connected Windows Server machines whose licences have active Software Assurance or are active subscription licences. After attestation, Azure Update Manager, Change Tracking and Inventory, Machine Configuration, Windows Admin Center in Azure, Remote Support, Best Practices Assessment, Azure Site Recovery configuration and discounted Azure File Sync are provided at no extra cost (log ingestion and downstream service costs still apply).", "prerequisites": ["Windows Server licences with active Software Assurance or an active subscription; attestation in the Azure portal"], "source": "https://learn.microsoft.com/azure/azure-arc/servers/windows-server-management-overview" },
  { "id": "esu-arc-windows", "name": "Extended Security Updates for Windows Server enabled by Azure Arc", "family": "azure", "type": "consumption", "rank": 8, "note": "Critical and Important security updates for Windows Server 2012/2012 R2 and 2016 after end of support, for up to three years, delivered to Arc-connected machines with no ESU product keys. Billed monthly pay-as-you-go through Azure and can draw down a MACC. Windows Server 2016 ESUs are configurable from 3 August 2026 with billing from 13 January 2027.", "prerequisites": ["Server connected to Azure Arc and in a Connected state"], "source": "https://learn.microsoft.com/azure/azure-arc/servers/prepare-extended-security-updates" },
  { "id": "esu-arc-sql", "name": "SQL Server Extended Security Updates enabled by Azure Arc", "family": "azure", "type": "consumption", "rank": 8, "note": "Security updates for SQL Server after end of support, for up to three years, billed on an hourly pay-as-you-go meter through Azure and cancellable at any time. Billed per virtual core (minimum four) or, with unlimited virtualisation, per physical core (minimum 16, Enterprise-edition meter). Software Assurance or a SQL Server subscription is a prerequisite for the program.", "prerequisites": ["SQL Server instance connected to Azure Arc; Software Assurance or a SQL Server subscription for the program"], "source": "https://learn.microsoft.com/sql/sql-server/azure-arc/extended-security-updates" },
  { "id": "arc-sql", "name": "SQL Server enabled by Azure Arc", "family": "azure", "type": "consumption", "rank": 8, "note": "Connects on-premises or other-cloud SQL Server instances to Azure. Offers a pay-as-you-go billing model (billed hourly through Azure) as an alternative to buying licences, for all versions from 2012 to 2022, licensed by virtual cores or by physical cores with unlimited virtualisation. Bring-your-own-licence is also supported, but unlimited virtualisation and features such as monitoring require Software Assurance or a subscription.", "prerequisites": ["Azure extension for SQL Server installed via the Azure Connected Machine agent"], "source": "https://learn.microsoft.com/sql/sql-server/azure-arc/manage-license-billing" },
  { "id": "azure-local", "name": "Azure Local", "family": "azure", "type": "consumption", "rank": 10, "note": "Microsoft's hybrid infrastructure platform (formerly Azure Stack HCI). Billed as an Azure service at a flat rate per physical processor core in the on-premises cluster, through your Azure subscription. No traditional on-premises software licence, but guest VM operating systems still need licensing. Requires a connection to Azure at least every 30 days.", "prerequisites": ["Registered Azure subscription; cluster connected to Azure"], "source": "https://learn.microsoft.com/azure/azure-local/concepts/billing" },
  { "id": "avs", "name": "Azure VMware Solution", "family": "azure", "type": "consumption", "rank": 20, "note": "VMware vSphere private clouds on dedicated bare-metal Azure hosts. Billed by the number and size of hosts (minimum three per private cloud), not by VM. VMware components (vSphere, vSAN, NSX, HCX) are included; guest Windows Server, SQL Server and Linux still need licensing. Reserved instances (one or three year) include the software licensing cost.", "prerequisites": ["An Enterprise Agreement, Microsoft Customer Agreement or CSP Azure plan; approved host quota"], "source": "https://learn.microsoft.com/azure/azure-vmware/introduction" },
  { "id": "azure-ai-foundry", "name": "Azure AI Foundry model consumption", "family": "azure", "type": "consumption", "rank": 12, "note": "Standard (pay-as-you-go) deployment of Azure OpenAI and other Foundry models, billed per input and output token. Foundry Agent Service adds no separate fee: agents are billed for the underlying model inference, plus Code Interpreter per session and File Search on vector storage.", "prerequisites": ["An Azure AI Foundry project / Azure OpenAI resource"], "source": "https://learn.microsoft.com/azure/ai-foundry/openai/concepts/provisioned-throughput" },
  { "id": "azure-openai-ptu", "name": "Azure AI Foundry Provisioned Throughput (PTU)", "family": "azure", "type": "consumption", "rank": 20, "note": "Provisioned Throughput Units reserve dedicated model-processing capacity for predictable latency and throughput. Granted as regional quota and billed hourly on the number of deployed PTUs regardless of utilisation. Quota is model-independent within a region and deployment type (Global, Data Zone, Regional).", "prerequisites": ["PTU quota in the target region and deployment type"], "source": "https://learn.microsoft.com/azure/ai-foundry/openai/how-to/provisioned-throughput-onboarding" },
  { "id": "azure-openai-ptu-reservation", "name": "Azure Reservation for Azure AI Foundry Provisioned Throughput", "family": "azure", "type": "benefit", "rank": 18, "note": "A term discount on top of the hourly PTU rate, committing to a fixed number of PTUs for one month or one year. Purchased in the Azure portal, scoped flexibly (resource group, subscription, management group or billing account). Separate reservations are needed per deployment type; PTUs beyond the reserved amount bill at the hourly rate.", "prerequisites": ["Existing or planned provisioned deployments (azure-openai-ptu)"], "source": "https://learn.microsoft.com/azure/cost-management-billing/reservations/azure-openai" },
  { "id": "powerbi-embedded", "name": "Power BI Embedded (A SKUs)", "family": "azure", "type": "consumption", "rank": 15, "note": "Azure-billed capacity (A1-A8) for embedding Power BI content in custom applications, especially the app-owns-data model where end users are unlicensed. Billed hourly and can be paused to stop billing. A SKUs below the F64/P1 equivalent still require each internal viewer to hold Pro or PPU.", "prerequisites": ["An Azure subscription; a Pro or PPU licence to publish the content"], "source": "https://learn.microsoft.com/power-bi/developer/embedded/embedded-capacity-planning" },
  { "id": "azure-devops-basic", "name": "Azure DevOps Basic access", "family": "azure", "type": "standalone", "rank": 10, "note": "Per-user access level for Azure Boards, Repos, Pipelines and Artifacts. The first five users in an organisation are free; beyond that each assigned Basic user is billed to the linked Azure subscription. Included with Visual Studio Professional and Enterprise subscriptions.", "prerequisites": ["An Azure DevOps organisation with billing linked to an Azure subscription"], "source": "https://learn.microsoft.com/azure/devops/organizations/billing/overview" },
  { "id": "azure-devops-test-plans", "name": "Azure DevOps Basic + Test Plans", "family": "azure", "type": "standalone", "rank": 16, "note": "The Basic access level plus Azure Test Plans for planned manual testing, exploratory testing and stakeholder feedback. A per-user add-on billed to the linked Azure subscription; included with Visual Studio Enterprise subscriptions.", "prerequisites": ["An Azure DevOps organisation with billing linked to an Azure subscription"], "source": "https://learn.microsoft.com/azure/devops/organizations/billing/buy-basic-access-add-users" },
  { "id": "azure-pipelines-parallel", "name": "Azure Pipelines parallel jobs", "family": "azure", "type": "consumption", "rank": 8, "note": "Extra concurrency for CI/CD. The no-cost tier gives one Microsoft-hosted job (with a monthly minute cap) and one self-hosted job per organisation; the self-hosted no-cost tier also adds one job per active Visual Studio Enterprise subscriber. Additional Microsoft-hosted or self-hosted parallel jobs are a fixed monthly charge per job on the Azure subscription.", "prerequisites": ["An Azure DevOps organisation with billing linked to an Azure subscription"], "source": "https://learn.microsoft.com/azure/devops/pipelines/licensing/concurrent-jobs" },
  { "id": "ghazdo", "name": "GitHub Advanced Security for Azure DevOps", "family": "azure", "type": "consumption", "rank": 15, "note": "Secret scanning with push protection, code scanning and dependency review for Azure Repos. Billed monthly to the Azure subscription per active committer - anyone in a push to an Advanced Security-enabled repo within the last 90 days - deduplicated across the subscription. Sold bundled or as the standalone Secret Protection and Code Security products.", "prerequisites": ["Azure Repos; billing linked to an Azure subscription"], "source": "https://learn.microsoft.com/azure/devops/repos/security/github-advanced-security-billing" },
  { "id": "azure-dedicated-host", "name": "Azure Dedicated Host", "family": "azure", "type": "consumption", "rank": 22, "note": "A physical server dedicated to one Azure subscription, billed per host. Lets you bring Windows Server and SQL Server licences via Azure Hybrid Benefit; licensing the whole host with Windows Server Datacenter or SQL Server Enterprise plus Software Assurance grants unlimited virtualisation. Windows/SQL Server 2012 workloads on the host get Extended Security Updates at no extra charge.", "prerequisites": ["An Azure subscription; licences with Software Assurance for host-level bring-your-own-licence"], "source": "https://learn.microsoft.com/azure/virtual-machines/dedicated-hosts" },
  { "id": "github-enterprise", "name": "GitHub Enterprise", "family": "azure", "type": "standalone", "rank": 22, "note": "Seat-based licence for GitHub Enterprise Cloud, billed monthly per active user and payable through an Azure subscription. AI services (GitHub Copilot) and Advanced Security are priced separately.", "prerequisites": [], "source": "https://learn.microsoft.com/azure/devops/organizations/billing/overview" },
  { "id": "d365-sales-pro", "name": "Dynamics 365 Sales Professional", "family": "bizapps", "type": "standalone", "rank": 30, "note": "Core sales force automation (leads, opportunities, quotes, orders, in-app marketing) for teams that don't need Sales Enterprise's advanced customization or AI. Entities are a subset of Sales Enterprise.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/sales/overview" },
  { "id": "microsoft-relationship-sales", "name": "Microsoft Relationship Sales", "family": "bizapps", "type": "standalone", "rank": 58, "note": "Dynamics 365 Sales Enterprise plus LinkedIn Sales Navigator Advanced Plus, for relationship-led selling. Not available for direct purchase - bought through a Microsoft representative or partner.", "includes": ["d365-sales-ent"], "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/sales/buy-dynamics-365-sales" },
  { "id": "d365-cs-ent", "name": "Dynamics 365 Customer Service Enterprise", "family": "bizapps", "type": "standalone", "rank": 42, "note": "Full case and knowledge management, entitlements, SLAs, Copilot Service workspace, and the base features of the built-in service agents. Required for the voice and digital messaging add-ons.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/customer-service/implement/customer-service-workspace-system-requirements" },
  { "id": "d365-cs-pro", "name": "Dynamics 365 Customer Service Professional", "family": "bizapps", "type": "standalone", "rank": 28, "note": "Case management and knowledge base for smaller support teams. A subset of Customer Service Enterprise - no advanced routing, embedded intelligence, or the omnichannel add-ons.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/customer-service/implement/overview" },
  { "id": "d365-cs-digital-messaging", "name": "Digital Messaging add-on for Dynamics 365 Customer Service", "family": "bizapps", "type": "addon", "rank": 20, "note": "Adds web chat plus social, SMS, WhatsApp, Teams and custom Direct Line channels with unified routing. Includes Copilot Studio entitlements for building the agents used on those channels.", "prerequisites": ["Dynamics 365 Customer Service Enterprise"], "source": "https://learn.microsoft.com/dynamics365/customer-service/develop/extend-omnichannel" },
  { "id": "d365-cs-chat", "name": "Chat add-on for Dynamics 365 Customer Service", "family": "bizapps", "type": "addon", "rank": 16, "note": "Adds the web chat channel only (plus telephony via third-party providers). Includes Copilot Studio entitlements for chat agents. Less than the Digital Messaging add-on, which also covers social/SMS/WhatsApp.", "prerequisites": ["Dynamics 365 Customer Service Enterprise"], "source": "https://learn.microsoft.com/dynamics365/customer-service/develop/extend-omnichannel" },
  { "id": "d365-cs-voice", "name": "Voice Channel add-on for Dynamics 365 Customer Service", "family": "bizapps", "type": "addon", "rank": 22, "note": "Adds Microsoft's native PSTN voice channel (built on Azure Communication Services) to Customer Service, with call transcription, sentiment and unified routing. Azure Communication Services telephony usage is billed separately.", "prerequisites": ["Dynamics 365 Customer Service Enterprise", "Digital Messaging or Chat add-on"], "source": "https://learn.microsoft.com/dynamics365/customer-service/administer/voice-channel-install" },
  { "id": "d365-contact-center", "name": "Dynamics 365 Contact Center", "family": "bizapps", "type": "standalone", "rank": 40, "note": "Microsoft's standalone AI-first contact-center solution (voice, digital channels, unified routing, Copilot). Can run on top of Dynamics 365 Customer Service or a third-party CRM ('Contact Center - embedded' vs '- standalone').", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/contact-center/implement/system-requirements-contact-center" },
  { "id": "d365-field-service", "name": "Dynamics 365 Field Service", "family": "bizapps", "type": "standalone", "rank": 40, "note": "Work-order management, scheduling and dispatch, inventory, and the Field Service mobile app for frontline technicians. The mobile app is included with the licence.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/field-service/buy-fs" },
  { "id": "d365-field-service-contractor", "name": "Dynamics 365 Field Service Contractor", "family": "bizapps", "type": "standalone", "rank": 18, "note": "A reduced Field Service licence for third-party technicians (typically added as Microsoft Entra B2B collaboration users) - a subset of the full Field Service features and capabilities.", "prerequisites": ["At least one full Dynamics 365 Field Service licence in the tenant"], "source": "https://learn.microsoft.com/dynamics365/field-service/buy-fs" },
  { "id": "d365-remote-assist", "name": "Dynamics 365 Remote Assist", "family": "bizapps", "type": "standalone", "rank": 20, "note": "Mixed-reality remote expert calling on HoloLens, mobile and Teams; a Microsoft Teams licence is included. Reaching end of support on 31 December 2026.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/mixed-reality/remote-assist/requirements" },
  { "id": "d365-guides", "name": "Dynamics 365 Guides", "family": "bizapps", "type": "standalone", "rank": 20, "note": "Step-by-step holographic work instructions on HoloLens, with a PC authoring app; Dataverse and Power Apps are included. A Teams licence is not included. Reaching end of support on 31 December 2026.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/mixed-reality/guides/requirements" },
  { "id": "d365-customer-insights", "name": "Dynamics 365 Customer Insights", "family": "bizapps", "type": "standalone", "rank": 42, "note": "The unified Customer Insights licence (sold since Sept 2023) covering both Customer Insights - Data (CDP) and Customer Insights - Journeys (real-time marketing). Entitles a base volume of unified people and interacted people; capacity add-ons increase both.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/customer-insights/journeys/purchase" },
  { "id": "d365-customer-insights-attach", "name": "Dynamics 365 Customer Insights (attach)", "family": "bizapps", "type": "addon", "rank": 30, "note": "Reduced-rate Customer Insights licence for tenants that already run a qualifying Dynamics 365 app (Sales, Customer Service, Field Service, Supply Chain, Finance or Commerce) with 10 or more users.", "prerequisites": ["A qualifying Dynamics 365 app with 10+ users"], "source": "https://learn.microsoft.com/dynamics365/customer-insights/journeys/purchase" },
  { "id": "d365-finance", "name": "Dynamics 365 Finance", "family": "bizapps", "type": "standalone", "rank": 52, "note": "Core financials - general ledger, AP, AR, budgeting, fixed assets, financial reporting. A finance and operations 'base' licence that other finance and operations apps can attach to.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/fin-ops-core/dev-itpro/lifecycle-services/expired-subscription-data-deletion" },
  { "id": "d365-scm", "name": "Dynamics 365 Supply Chain Management", "family": "bizapps", "type": "standalone", "rank": 52, "note": "Inventory, warehouse, manufacturing, procurement and planning. A finance and operations 'base' licence; also commonly bought as an attach licence for Finance users.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/fin-ops-core/dev-itpro/lifecycle-services/expired-subscription-data-deletion" },
  { "id": "d365-commerce", "name": "Dynamics 365 Commerce", "family": "bizapps", "type": "standalone", "rank": 50, "note": "Unified retail across in-store POS, call centre and e-commerce, built on the finance and operations platform. A base licence in the base + attach model.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/fin-ops-core/dev-itpro/lifecycle-services/expired-subscription-data-deletion" },
  { "id": "d365-human-resources", "name": "Dynamics 365 Human Resources", "family": "bizapps", "type": "standalone", "rank": 40, "note": "Core HR - employee records, leave and absence, benefits, compensation. A finance and operations base licence; Human Resources Self Service is a lighter companion licence.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/fin-ops-core/dev-itpro/lifecycle-services/expired-subscription-data-deletion" },
  { "id": "d365-project-operations", "name": "Dynamics 365 Project Operations", "family": "bizapps", "type": "standalone", "rank": 48, "note": "Connects project sales, resourcing, project management (Project for the web) and project accounting. A base licence; the 'integrated with ERP' deployment additionally needs Finance/Supply Chain Management.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/project-operations/welcome-to-project-operations" },
  { "id": "d365-ops-activity", "name": "Dynamics 365 Operations - Activity", "family": "bizapps", "type": "standalone", "rank": 16, "note": "A light-use finance and operations licence for users who perform a limited set of operational tasks. One 'write' privilege outside the allowed scope escalates the user to a full base licence.", "prerequisites": ["A full finance and operations base licence in the tenant"], "source": "https://learn.microsoft.com/dynamics365/fin-ops-core/dev-itpro/sysadmin/prepare-for-user-validation" },
  { "id": "d365-attach", "name": "Dynamics 365 attach (subsequent qualifying app)", "family": "bizapps", "type": "addon", "rank": 25, "note": "Not a product in itself - the reduced 'Attach to Qualifying Dynamics 365 Base Offer' rate at which a user who already holds one full base licence can license additional qualifying Dynamics 365 apps. Assign the base licence first, then the attach.", "prerequisites": ["One full Dynamics 365 base licence assigned to the same user"], "source": "https://learn.microsoft.com/dynamics365/fin-ops-core/dev-itpro/lifecycle-services/expired-subscription-data-deletion" },
  { "id": "d365-device", "name": "Dynamics 365 Device license", "family": "bizapps", "type": "standalone", "rank": 20, "note": "A device-based licence for shared scenarios (shop floor, warehouse, retail) where many users take turns on one device using shared or individual sign-ins, instead of a named-user licence each.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/fin-ops-core/dev-itpro/lifecycle-services/expired-subscription-data-deletion" },
  { "id": "operations-db-capacity", "name": "Dynamics 365 Operations - Database Capacity", "family": "bizapps", "type": "addon", "rank": 12, "note": "Tenant-level add-on that increases database storage for finance and operations environments. Database entitlement is pooled with Dataverse database capacity for enforcement.", "prerequisites": ["A finance and operations app subscription"], "source": "https://learn.microsoft.com/power-platform/admin/capacity-storage" },
  { "id": "operations-file-capacity", "name": "Dynamics 365 Operations - File Capacity", "family": "bizapps", "type": "addon", "rank": 10, "note": "Tenant-level add-on that increases file storage for finance and operations environments; pooled with Dataverse file capacity.", "prerequisites": ["A finance and operations app subscription"], "source": "https://learn.microsoft.com/power-platform/admin/capacity-storage" },
  { "id": "bc-essentials", "name": "Dynamics 365 Business Central Essentials", "family": "bizapps", "type": "standalone", "rank": 35, "note": "All-in-one ERP for SMBs - financials, sales, purchasing, inventory, projects. Full read/write access to Essentials companies. Sold only through CSP.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/business-central/dev-itpro/deployment/licensing" },
  { "id": "bc-premium", "name": "Dynamics 365 Business Central Premium", "family": "bizapps", "type": "standalone", "rank": 42, "note": "Business Central Essentials plus manufacturing and service management. Premium features are enabled per company; a Premium user can also open Essentials companies but not use Premium-only features there.", "includes": ["bc-essentials"], "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/business-central/dev-itpro/administration/tenant-admin-center-manage-access" },
  { "id": "bc-team-members", "name": "Dynamics 365 Business Central Team Members", "family": "bizapps", "type": "standalone", "rank": 12, "note": "Light Business Central access - read all data, plus a limited set of write scenarios (e.g. time sheets, approvals). Not for full operational use. Distinct from the Dynamics 365 (customer engagement) Team Members licence.", "prerequisites": ["A Business Central Essentials or Premium licence in the tenant"], "source": "https://learn.microsoft.com/dynamics365/business-central/admin-access-with-m365-license" },
  { "id": "bc-device", "name": "Dynamics 365 Business Central Device", "family": "bizapps", "type": "standalone", "rank": 18, "note": "Device licence letting multiple users share a covered device (POS, shop floor, warehouse). Members of the 'Dynamics 365 Business Central Device Users' group don't each need a user licence; a device user can't be the first to sign in.", "prerequisites": [], "source": "https://learn.microsoft.com/dynamics365/business-central/dev-itpro/deployment/licensing" },
  { "id": "project-plan3", "name": "Project Plan 3", "family": "bizapps", "type": "standalone", "rank": 20, "note": "Desktop and web project scheduling, including Project for the web. Grants premium Power Platform/Dataverse rights in the project context and is a qualifying base for Project Operations resourcing.", "prerequisites": [], "source": "https://learn.microsoft.com/power-platform/admin/pricing-billing-skus" },
  { "id": "project-plan5", "name": "Project Plan 5", "family": "bizapps", "type": "standalone", "rank": 25, "note": "Project Plan 3 plus portfolio selection, demand management and enterprise resource capacity planning.", "prerequisites": [], "source": "https://learn.microsoft.com/power-platform/admin/pricing-billing-skus" },
  { "id": "powerapps-per-app", "name": "Power Apps per app plan", "family": "bizapps", "type": "standalone", "rank": 18, "note": "Per-user, per-app licence: rights to run one app (canvas and/or model-driven) or one Power Pages site in a single environment, with full premium capabilities. Stackable - a user can hold several. Allocated to environments, not assigned to users directly.", "prerequisites": [], "source": "https://learn.microsoft.com/power-platform/admin/powerapps-flow-licensing-faq" },
  { "id": "powerapps-payg", "name": "Power Apps pay-as-you-go", "family": "bizapps", "type": "consumption", "rank": 15, "note": "Run and share apps with no licence commitment, billed monthly through an Azure subscription per unique active user per app. Set at the environment level; requires an Azure subscription; per-app licences can't be used in a pay-as-you-go environment.", "prerequisites": ["An Azure subscription linked as a billing plan"], "source": "https://learn.microsoft.com/power-platform/admin/pay-as-you-go-overview" },
  { "id": "powerapps-developer-plan", "name": "Power Apps Developer Plan", "family": "bizapps", "type": "standalone", "rank": 5, "note": "No-cost, individual, self-service plan providing a personal Developer environment with Dataverse and premium/custom connectors for building and testing (not production). 2 GB database, 750 flow runs/month; can't be extended with add-ons.", "prerequisites": [], "source": "https://learn.microsoft.com/power-platform/developer/plan" },
  { "id": "powerautomate-free", "name": "Power Automate Free", "family": "bizapps", "type": "standalone", "rank": 5, "note": "No-cost for work/school accounts: create and run cloud flows with standard connectors only (no sharing), and author/run desktop flows locally in attended mode.", "prerequisites": [], "source": "https://learn.microsoft.com/power-platform/admin/power-automate-licensing/types" },
  { "id": "powerautomate-process", "name": "Power Automate Process", "family": "bizapps", "type": "standalone", "rank": 25, "note": "Capacity licence allocated to a single cloud flow (higher action limits, premium/custom connectors regardless of triggering user) or to a machine as one unattended RPA bot. Flows must be in a solution. Stackable up to 10 per flow.", "prerequisites": [], "source": "https://learn.microsoft.com/power-platform/admin/power-automate-licensing/types" },
  { "id": "powerautomate-hosted-process", "name": "Power Automate Hosted Process", "family": "bizapps", "type": "standalone", "rank": 28, "note": "Capacity licence providing one Microsoft-hosted RPA bot - unattended desktop automation with no physical machine to manage. A superset of Power Automate Process. Sometimes called the hosted RPA add-on.", "prerequisites": ["A machine registered by a Power Automate Premium user for the triggering connection"], "source": "https://learn.microsoft.com/power-platform/admin/power-automate-licensing/types" },
  { "id": "powerautomate-payg", "name": "Power Automate pay-as-you-go", "family": "bizapps", "type": "consumption", "rank": 15, "note": "Pay for cloud-flow runs above the per-user/per-flow daily entitlement through an Azure subscription, metered as Power Platform requests. Also the pay-as-you-go option for Copilot Studio messages.", "prerequisites": ["An Azure subscription linked as a billing plan"], "source": "https://learn.microsoft.com/power-platform/admin/pay-as-you-go-meters" },
  { "id": "powerpages-authenticated", "name": "Power Pages authenticated users capacity", "family": "bizapps", "type": "consumption", "rank": 18, "note": "Capacity for unique authenticated (signed-in) users per website per month - sold as subscription capacity packs or as a pay-as-you-go meter. Includes some Dataverse database and file storage. Minimum 25 authenticated users assigned per environment.", "prerequisites": [], "source": "https://learn.microsoft.com/power-platform/admin/powerapps-flow-licensing-faq" },
  { "id": "powerpages-anonymous", "name": "Power Pages anonymous users capacity", "family": "bizapps", "type": "consumption", "rank": 15, "note": "Capacity for unique anonymous (not signed-in) users per website per month - subscription packs or a pay-as-you-go meter. The sign-in page alone doesn't count. Minimum 200 anonymous users assigned per environment.", "prerequisites": [], "source": "https://learn.microsoft.com/power-platform/admin/powerapps-flow-licensing-faq" },
  { "id": "dataverse-db-capacity", "name": "Microsoft Dataverse Database Capacity", "family": "bizapps", "type": "addon", "rank": 12, "note": "Per-GB add-on that increases the tenant's Dataverse database storage entitlement (the pooled base capacity plus per-user accruals). Bought in 1-GB increments.", "prerequisites": ["A Power Platform or Dynamics 365 subscription"], "source": "https://learn.microsoft.com/power-platform/admin/capacity-storage" },
  { "id": "dataverse-file-capacity", "name": "Microsoft Dataverse File Capacity", "family": "bizapps", "type": "addon", "rank": 10, "note": "Per-GB add-on that increases the tenant's Dataverse file storage entitlement. Database capacity can offset file overages, but not the reverse.", "prerequisites": ["A Power Platform or Dynamics 365 subscription"], "source": "https://learn.microsoft.com/power-platform/admin/capacity-storage" },
  { "id": "dataverse-log-capacity", "name": "Microsoft Dataverse Log Capacity", "family": "bizapps", "type": "addon", "rank": 8, "note": "Per-GB add-on that increases the tenant's Dataverse log storage entitlement (auditing, plug-in trace, elastic tables). Tracked separately from database and file.", "prerequisites": ["A Power Platform or Dynamics 365 subscription"], "source": "https://learn.microsoft.com/power-platform/admin/capacity-storage" },
  { "id": "dataverse-teams", "name": "Microsoft Dataverse for Teams", "family": "bizapps", "type": "standalone", "rank": 10, "note": "Included with select Microsoft 365 subscriptions that have Power Platform and Teams capabilities. One environment per team (~1M rows / 2 GB), Teams channels only, no premium/custom connectors, AI Builder or desktop flows without additional Power Apps/Automate licensing.", "prerequisites": ["A qualifying Microsoft 365 subscription with Power Platform + Teams"], "source": "https://learn.microsoft.com/power-platform/admin/about-teams-environment" },
  { "id": "ai-builder-addon", "name": "AI Builder capacity add-on", "family": "bizapps", "type": "addon", "rank": 15, "note": "Tenant-pooled AI Builder service credits (1M per unit per month) consumed by AI Builder models in Power Apps, Power Automate and Dynamics 365. New customers now buy Copilot Credits instead; seeded credits in premium licences end 1 Nov 2026.", "prerequisites": [], "source": "https://learn.microsoft.com/ai-builder/credit-management" },
  { "id": "copilot-credits", "name": "Microsoft Copilot Studio capacity (Copilot Credits)", "family": "bizapps", "type": "consumption", "rank": 20, "note": "The consumption currency for published Copilot Studio agents, Copilot Chat/SharePoint agents and many AI Builder scenarios. Bought as prepaid capacity packs (25,000 credits/month each) and/or metered pay-as-you-go via an Azure subscription; allocated to environments in the Power Platform admin center.", "prerequisites": [], "source": "https://learn.microsoft.com/microsoft-365/copilot/pay-as-you-go/copilot-capacity-packs" },
  { "id": "copilot-studio-teams", "name": "Microsoft Copilot Studio for Teams", "family": "bizapps", "type": "standalone", "rank": 12, "note": "A subset of Copilot Studio included with select Microsoft 365 subscriptions: classic-orchestration agents published to Teams, using Dataverse for Teams. No generative orchestration, premium connectors, other channels or live handoff.", "prerequisites": ["A qualifying Microsoft 365 subscription with Power Platform + Teams"], "source": "https://learn.microsoft.com/microsoft-copilot-studio/requirements-licensing-subscriptions" },
  { "id": "powerbi-free", "name": "Power BI (Fabric free) per-user license", "family": "bizapps", "type": "standalone", "rank": 5, "note": "Free per-user licence: build content for personal use, and consume content shared by Pro/PPU users when it sits in a Fabric F64+ or Power BI Premium capacity. Cannot publish or share in shared capacity.", "prerequisites": [], "source": "https://learn.microsoft.com/power-bi/fundamentals/service-features-license-type" }
